sp_widget.client_script:
function($scope, $window) {

    var c = this;


    // =====================================================
    // INITIAL STATE
    // =====================================================

    c.loading = false;


    // =====================================================
    // REFRESH DATA
    // =====================================================

    c.refreshData = function() {

        c.loading = true;

        c.server.update().then(function() {

            c.loading = false;

        }, function() {

            c.loading = false;

        });

    };


    // =====================================================
    // EXPEDITE CASE
    // =====================================================

    c.expediteCase = function(caseItem) {

        if (!caseItem) {
            return;
        }

        alert(
            "Case " +
            caseItem.case_id +
            " has been marked for expedited review."
        );

    };


    // =====================================================
    // INITIAL DATA SAFETY
    // =====================================================

    if (!c.data.slaStats) {

        c.data.slaStats = {

            onTrack: 0,
            atRisk: 0,
            breached: 0,
            avgResolutionDays: 0

        };

    }


    if (!c.data.riskDistribution) {

        c.data.riskDistribution = [];

    }


    if (!c.data.watchlistCases) {

        c.data.watchlistCases = [];

    }

}

sp_widget.css:
/* =========================================================
   VISA GUARDIAN AI
   RISK & SLA ANALYTICS
   PREMIUM ENTERPRISE UI
   ========================================================= */

.vg-analytics-container {
    width: 100%;
    min-height: 100vh;

    padding: 0;
    margin: 0;

    box-sizing: border-box;

    background:
        linear-gradient(
            180deg,
            #f5f8fd 0%,
            #f1f5fa 100%
        );

    color: #173f6d;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Helvetica,
        Arial,
        sans-serif;

    -webkit-font-smoothing: antialiased;
}


/* =========================================================
   GLOBAL BOX SIZING
   ========================================================= */

.vg-analytics-container *,
.vg-analytics-container *::before,
.vg-analytics-container *::after {
    box-sizing: border-box;
}


/* =========================================================
   HERO
   ========================================================= */

.vg-analytics-container .vg-hero-banner {
    position: relative;

    width: 100%;
    min-height: 140px;

    padding: 27px 38px;

    margin-bottom: 26px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            #091f3c 0%,
            #103d73 55%,
            #2167b5 100%
        );

    border-radius: 17px;

    color: #ffffff;

    box-shadow:
        0 12px 30px
        rgba(9, 35, 65, .16);
}


/* Hero decorative glow */

.vg-analytics-container .vg-hero-banner::before {
    content: "";

    position: absolute;

    width: 280px;
    height: 280px;

    right: -100px;
    top: -145px;

    border-radius: 50%;

    background:
        rgba(255,255,255,.055);

    pointer-events: none;
}


.vg-analytics-container .vg-hero-banner::after {
    content: "";

    position: absolute;

    width: 170px;
    height: 170px;

    right: 20%;
    bottom: -135px;

    border-radius: 50%;

    background:
        rgba(74,157,255,.06);

    pointer-events: none;
}


/* =========================================================
   HERO CONTENT
   ========================================================= */

.vg-analytics-container .hero-content {
    position: relative;

    z-index: 2;
}


.vg-analytics-container .hero-content h2 {
    margin: 0 0 7px;

    color: #ffffff;

    font-size: 27px;

    line-height: 1.2;

    font-weight: 750;

    letter-spacing: -.4px;
}


.vg-analytics-container .hero-content p {
    margin: 0;

    color:
        rgba(255,255,255,.78);

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   HERO BUTTON
   ========================================================= */

.vg-analytics-container .btn-hero-outline {
    position: relative;

    z-index: 3;

    padding:
        10px 18px;

    border:
        1px solid
        rgba(255,255,255,.35);

    border-radius:
        9px;

    background:
        rgba(255,255,255,.08);

    color:
        #ffffff;

    font-size:
        12px;

    font-weight:
        700;

    transition:
        all .2s ease;
}


.vg-analytics-container .btn-hero-outline:hover {
    background:
        #ffffff;

    color:
        #123e70;

    border-color:
        #ffffff;

    transform:
        translateY(-1px);

    box-shadow:
        0 5px 14px
        rgba(0,0,0,.15);
}


/* =========================================================
   METRIC ROW
   ========================================================= */

.vg-analytics-container .metric-row {
    margin-left: -10px;

    margin-right: -10px;

    margin-bottom: 5px;
}


.vg-analytics-container .metric-row > [class*="col-"] {
    padding-left: 10px;

    padding-right: 10px;

    margin-bottom: 20px;
}


/* =========================================================
   METRIC CARDS
   ========================================================= */

.vg-analytics-container .vg-metric-card {
    position: relative;

    min-height: 112px;

    padding: 20px 22px;

    display: flex;

    align-items: center;

    gap: 17px;

    overflow: hidden;

    background:
        #ffffff;

    border:
        1px solid
        #e1e8f1;

    border-radius:
        15px;

    box-shadow:
        0 6px 18px
        rgba(31,62,98,.055);

    transition:
        transform .2s ease,
        box-shadow .2s ease,
        border-color .2s ease;
}


.vg-analytics-container .vg-metric-card:hover {
    transform:
        translateY(-3px);

    border-color:
        #d2deec;

    box-shadow:
        0 12px 28px
        rgba(31,62,98,.10);
}


/* Decorative metric circle */

.vg-analytics-container .vg-metric-card::after {
    content: "";

    position: absolute;

    width: 105px;
    height: 105px;

    right: -50px;
    bottom: -55px;

    border-radius: 50%;

    background:
        rgba(37,99,235,.025);

    pointer-events: none;
}


/* =========================================================
   METRIC ICONS
   ========================================================= */

.vg-analytics-container .metric-icon {
    width: 54px;
    height: 54px;

    min-width: 54px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 15px;

    font-size: 21px;

    position: relative;

    z-index: 2;
}


.vg-analytics-container .red-circle {
    background:
        #feecee;

    color:
        #e54855;
}


.vg-analytics-container .orange-circle {
    background:
        #fff4df;

    color:
        #e58b18;
}


.vg-analytics-container .green-circle {
    background:
        #eaf8ef;

    color:
        #0aa66b;
}


.vg-analytics-container .blue-circle {
    background:
        #eaf2ff;

    color:
        #2563eb;
}


/* =========================================================
   METRIC DATA
   ========================================================= */

.vg-analytics-container .metric-data {
    display:
        flex;

    flex-direction:
        column;

    position:
        relative;

    z-index:
        2;
}


.vg-analytics-container .metric-number {
    font-size:
        28px;

    line-height:
        30px;

    font-weight:
        800;

    letter-spacing:
        -.4px;
}


.vg-analytics-container .metric-label {
    margin-top:
        5px;

    color:
        #8494aa;

    font-size:
        10px;

    line-height:
        15px;

    font-weight:
        800;

    letter-spacing:
        .7px;

    text-transform:
        uppercase;
}


.vg-analytics-container .metric-subtext {
    margin-top:
        2px;

    font-size:
        11px;

    line-height:
        16px;

    font-weight:
        600;
}


/* =========================================================
   SEMANTIC COLORS
   ========================================================= */

.vg-analytics-container .text-red {
    color:
        #df414e !important;
}


.vg-analytics-container .text-orange {
    color:
        #d9820b !important;
}


.vg-analytics-container .text-green {
    color:
        #079b63 !important;
}


.vg-analytics-container .text-blue {
    color:
        #2563eb !important;
}


/* =========================================================
   GENERAL CARDS
   ========================================================= */

.vg-analytics-container .vg-card {
    width:
        100%;

    padding:
        25px 27px;

    margin-bottom:
        22px;

    background:
        #ffffff;

    border:
        1px solid
        #e0e8f1;

    border-radius:
        17px;

    box-shadow:
        0 7px 22px
        rgba(31,62,98,.055);
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.vg-analytics-container .vg-card-header {
    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    gap:
        20px;

    padding-bottom:
        18px;

    margin-bottom:
        17px;

    border-bottom:
        1px solid
        #e7edf4;
}


.vg-analytics-container .vg-card-header h4 {
    margin:
        0;

    color:
        #173f6d;

    font-size:
        18px;

    line-height:
        1.3;

    font-weight:
        750;
}


.vg-analytics-container .vg-card-header h4 i {
    margin-right:
        8px;

    color:
        #2563eb;
}


/* Watchlist count */

.vg-analytics-container .watchlist-count {
    padding:
        6px 10px;

    border-radius:
        20px;

    background:
        #f1f6ff;

    color:
        #8293ab;

    font-size:
        11px;

    font-weight:
        650;
}


/* =========================================================
   RISK DISTRIBUTION
   ========================================================= */

.vg-analytics-container .risk-breakdown-list {
    display:
        flex;

    flex-direction:
        column;

    gap:
        20px;
}


.vg-analytics-container .risk-header {
    display:
        flex;

    justify-content:
        space-between;

    align-items:
        center;

    margin-bottom:
        8px;
}


.vg-analytics-container .risk-name {
    color:
        #193858;

    font-size:
        13px;

    font-weight:
        750;
}


.vg-analytics-container .risk-name i {
    margin-right:
        7px;

    font-size:
        8px;
}


.vg-analytics-container .risk-count {
    color:
        #8797ad;

    font-size:
        11px;
}


.vg-analytics-container .risk-count strong {
    color:
        #193858;

    font-size:
        13px;
}


.vg-analytics-container .percentage {
    margin-left:
        5px;

    font-weight:
        750;
}


/* =========================================================
   PROGRESS BAR
   ========================================================= */

.vg-analytics-container .vg-progress {
    height:
        9px;

    margin:
        0;

    overflow:
        hidden;

    border-radius:
        20px;

    background:
        #edf2f7;

    box-shadow:
        inset 0 1px 2px
        rgba(25,50,80,.03);
}


.vg-analytics-container .vg-progress .progress-bar {
    border-radius:
        20px;

    transition:
        width .4s ease;
}


/* =========================================================
   TOTAL CASES
   ========================================================= */

.vg-analytics-container .risk-total-box {
    margin-top:
        22px;

    padding:
        14px 16px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    border:
        1px solid
        #e5ebf2;

    border-radius:
        11px;

    background:
        #f8fafc;

    color:
        #8494aa;

    font-size:
        12px;

    font-weight:
        600;
}


.vg-analytics-container .risk-total-box strong {
    color:
        #173f6d;

    font-size:
        21px;

    font-weight:
        800;
}


/* =========================================================
   SLA PERFORMANCE
   ========================================================= */

.vg-analytics-container .sla-performance {
    display:
        grid;

    grid-template-columns:
        1fr 1fr;

    gap:
        14px;
}


.vg-analytics-container .sla-stat {
    min-height:
        108px;

    display:
        flex;

    align-items:
        center;

    gap:
        13px;

    padding:
        17px;

    border:
        1px solid
        #e7edf4;

    border-radius:
        12px;

    background:
        #fbfcfe;

    transition:
        all .18s ease;
}


.vg-analytics-container .sla-stat:hover {
    background:
        #ffffff;

    border-color:
        #d9e4f0;

    transform:
        translateY(-2px);

    box-shadow:
        0 6px 16px
        rgba(31,62,98,.06);
}


/* SLA icons */

.vg-analytics-container .sla-stat-icon {
    width:
        42px;

    height:
        42px;

    min-width:
        42px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        11px;

    font-size:
        17px;
}


.vg-analytics-container .sla-stat-icon.green {
    background:
        #e8f8ee;

    color:
        #0aa66b;
}


.vg-analytics-container .sla-stat-icon.orange {
    background:
        #fff4df;

    color:
        #e58b18;
}


.vg-analytics-container .sla-stat-icon.red {
    background:
        #feecee;

    color:
        #df414e;
}


.vg-analytics-container .sla-stat-icon.blue {
    background:
        #eaf2ff;

    color:
        #2563eb;
}


/* SLA text */

.vg-analytics-container .sla-stat-content {
    display:
        flex;

    flex-direction:
        column;
}


.vg-analytics-container .sla-stat-title {
    color:
        #8293aa;

    font-size:
        10px;

    font-weight:
        800;

    letter-spacing:
        .4px;

    text-transform:
        uppercase;
}


.vg-analytics-container .sla-stat-content strong {
    margin-top:
        2px;

    color:
        #173f6d;

    font-size:
        23px;

    line-height:
        27px;

    font-weight:
        800;
}


.vg-analytics-container .sla-stat-description {
    margin-top:
        3px;

    color:
        #8c9bb0;

    font-size:
        10px;

    line-height:
        14px;
}


/* =========================================================
   WATCHLIST TABLE
   ========================================================= */

.vg-analytics-container .table-responsive {
    width:
        100%;

    overflow-x:
        auto;

    overflow-y:
        hidden;

    border-radius:
        10px;
}


.vg-analytics-container .vg-table {
    width:
        100%;

    min-width:
        980px;

    margin:
        0;

    border-collapse:
        separate;

    border-spacing:
        0;
}


/* Header */

.vg-analytics-container .vg-table th {
    padding:
        14px 11px;

    border-top:
        none;

    border-bottom:
        1px solid
        #e4ebf3;

    background:
        #f8fafc;

    color:
        #8292aa;

    font-size:
        10px;

    font-weight:
        800;

    letter-spacing:
        .65px;

    text-transform:
        uppercase;

    white-space:
        nowrap;
}


.vg-analytics-container .vg-table th:first-child {
    border-radius:
        9px 0 0 9px;
}


.vg-analytics-container .vg-table th:last-child {
    border-radius:
        0 9px 9px 0;
}


/* Rows */

.vg-analytics-container .vg-table tbody tr {
    transition:
        background .18s ease;
}


.vg-analytics-container .vg-table tbody tr:hover {
    background:
        #f8fbff;
}


.vg-analytics-container .vg-table td {
    padding:
        14px 11px;

    border-top:
        1px solid
        #edf1f5;

    color:
        #344f70;

    font-size:
        12px;

    vertical-align:
        middle;
}


.vg-analytics-container .vg-table tbody tr:first-child td {
    border-top:
        none;
}


/* =========================================================
   CASE ID
   ========================================================= */

.vg-analytics-container .case-id-badge {
    display:
        inline-block;

    padding:
        6px 10px;

    border:
        1px solid
        #dce8fb;

    border-radius:
        8px;

    background:
        #edf4ff;

    color:
        #2563eb;

    font-family:
        SFMono-Regular,
        Menlo,
        Monaco,
        Consolas,
        monospace;

    font-size:
        10px;

    font-weight:
        750;

    white-space:
        nowrap;
}


/* =========================================================
   STUDENT
   ========================================================= */

.vg-analytics-container .student-cell {
    display:
        flex;

    flex-direction:
        column;

    gap:
        3px;
}


.vg-analytics-container .student-name {
    color:
        #173554;

    font-size:
        13px;

    font-weight:
        750;

    white-space:
        nowrap;
}


.vg-analytics-container .student-id {
    color:
        #8b9aae;

    font-size:
        10px;

    margin-top:
        1px;
}


/* =========================================================
   TYPE BADGE
   ========================================================= */

.vg-analytics-container .type-badge {
    display:
        inline-block;

    padding:
        6px 10px;

    border:
        1px solid
        #e5e0ff;

    border-radius:
        8px;

    background:
        #f5f2ff;

    color:
        #6254c7;

    font-size:
        10px;

    font-weight:
        700;
}


/* =========================================================
   RISK BADGES
   ========================================================= */

.vg-analytics-container .risk-pill {
    display:
        inline-flex;

    align-items:
        center;

    gap:
        6px;

    padding:
        6px 10px;

    border-radius:
        8px;

    font-size:
        10px;

    font-weight:
        750;

    white-space:
        nowrap;
}


.vg-analytics-container .risk-pill small {
    font-size:
        9px;

    font-weight:
        650;
}


.vg-analytics-container .risk-high {
    background:
        #feecee;

    color:
        #df414e;
}


.vg-analytics-container .risk-med {
    background:
        #fff4df;

    color:
        #d9820b;
}


.vg-analytics-container .risk-low {
    background:
        #e8f8ee;

    color:
        #079b63;
}


/* =========================================================
   SLA STATUS
   ========================================================= */

.vg-analytics-container .sla-status {
    display:
        inline-flex;

    align-items:
        center;

    padding:
        6px 10px;

    border-radius:
        8px;

    font-size:
        10px;

    font-weight:
        750;

    white-space:
        nowrap;
}


.vg-analytics-container .sla-breached {
    background:
        #feecee;

    color:
        #df414e;
}


.vg-analytics-container .sla-risk {
    background:
        #fff4df;

    color:
        #d9820b;
}


.vg-analytics-container .sla-track {
    background:
        #e8f8ee;

    color:
        #079b63;
}


/* =========================================================
   SLA TIMER
   ========================================================= */

.vg-analytics-container .sla-timer-badge {
    display:
        inline-flex;

    align-items:
        center;

    gap:
        5px;

    padding:
        6px 10px;

    border-radius:
        8px;

    font-size:
        10px;

    font-weight:
        750;

    white-space:
        nowrap;
}


.vg-analytics-container .timer-danger {
    background:
        #feecee;

    color:
        #df414e;
}


.vg-analytics-container .timer-warning {
    background:
        #fff4df;

    color:
        #d9820b;
}


.vg-analytics-container .timer-normal {
    background:
        #e8f8ee;

    color:
        #079b63;
}


/* =========================================================
   REVIEW BUTTON
   ========================================================= */

.vg-analytics-container .btn-review {
    min-width:
        76px;

    padding:
        7px 12px;

    border:
        1px solid
        #d7e4f8;

    border-radius:
        8px;

    background:
        #f1f6ff;

    color:
        #2563eb;

    font-size:
        10px;

    font-weight:
        750;

    cursor:
        pointer;

    transition:
        all .18s ease;
}


.vg-analytics-container .btn-review:hover {
    background:
        #2563eb;

    border-color:
        #2563eb;

    color:
        #ffffff;

    transform:
        translateY(-1px);

    box-shadow:
        0 4px 11px
        rgba(37,99,235,.16);
}


/* =========================================================
   AI SUMMARY
   ========================================================= */

.vg-analytics-container .ai-summary-card {
    display:
        flex;

    align-items:
        flex-start;

    gap:
        16px;

    padding:
        21px 23px;

    background:
        linear-gradient(
            135deg,
            #f5f9ff 0%,
            #ffffff 100%
        );

    border:
        1px solid
        #dce8fa;

    border-left:
        4px solid
        #2563eb;

    border-radius:
        14px;

    box-shadow:
        0 5px 16px
        rgba(37,99,235,.05);
}


.vg-analytics-container .ai-summary-icon {
    width:
        43px;

    height:
        43px;

    min-width:
        43px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        11px;

    background:
        #eaf2ff;

    color:
        #2563eb;

    font-size:
        18px;
}


.vg-analytics-container .ai-summary-content h4 {
    margin:
        0 0 5px;

    color:
        #173f6d;

    font-size:
        15px;

    font-weight:
        750;
}


.vg-analytics-container .ai-summary-content p {
    margin:
        0;

    color:
        #5d6d82;

    font-size:
        12px;

    line-height:
        1.65;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.vg-analytics-container .pad-lg {
    padding:
        30px !important;
}


/* =========================================================
   SCROLLBAR
   ========================================================= */

.vg-analytics-container .table-responsive::-webkit-scrollbar {
    height:
        7px;
}


.vg-analytics-container .table-responsive::-webkit-scrollbar-track {
    background:
        #edf2f7;

    border-radius:
        10px;
}


.vg-analytics-container .table-responsive::-webkit-scrollbar-thumb {
    background:
        #c4d0de;

    border-radius:
        10px;
}


.vg-analytics-container .table-responsive::-webkit-scrollbar-thumb:hover {
    background:
        #aebdce;
}


/* =========================================================
   RESPONSIVE - TABLET
   ========================================================= */

