sp_widget.script:
(function() {

    // =====================================================
    // VISA CASE TABLE
    // =====================================================

    var CASE_TABLE = "x_snc_visaguardi_0_visa_case";


    // =====================================================
    // DEFAULT DATA
    // =====================================================

    data.slaStats = {
        onTrack: 0,
        atRisk: 0,
        breached: 0,
        avgResolutionDays: 0
    };

    data.riskDistribution = [];

    data.watchlistCases = [];

    data.aiInsight = "";


    // =====================================================
    // COUNTERS
    // =====================================================

    var totalCases = 0;

    var highRisk = 0;
    var mediumRisk = 0;
    var lowRisk = 0;

    var onTrack = 0;
    var atRisk = 0;
    var breached = 0;

    var resolvedCases = 0;
    var totalResolutionDays = 0;


    // =====================================================
    // GET VISA CASES
    // =====================================================

    var gr = new GlideRecord(CASE_TABLE);

    gr.orderByDesc("sys_created_on");

    gr.query();


    // =====================================================
    // PROCESS CASES
    // =====================================================

    while (gr.next()) {

        totalCases++;


        // =================================================
        // CASE ID
        // =================================================

        var caseId = "";

        if (gr.isValidField("number") &&
            gr.getValue("number")) {

            caseId = gr.getValue("number");

        } else {

            caseId = gr.getUniqueValue();

        }


        // =================================================
        // STUDENT
        // =================================================

        var studentName = "Unknown Student";

        if (gr.isValidField("student")) {

            studentName =
                gr.getDisplayValue("student") ||
                "Unknown Student";

        }


        // =================================================
        // CASE TYPE
        // =================================================

        var caseType = "Not Available";

        if (gr.isValidField("case_type")) {

            caseType =
                gr.getDisplayValue("case_type") ||
                gr.getValue("case_type") ||
                "Not Available";

        }


        // =================================================
        // CASE STAGE
        // =================================================

        var caseStage = "Pending";

        if (gr.isValidField("case_stage")) {

            caseStage =
                gr.getDisplayValue("case_stage") ||
                gr.getValue("case_stage") ||
                "Pending";

        }


        // =================================================
        // PRIORITY
        // =================================================

        var priority = "Medium";

        if (gr.isValidField("priority")) {

            priority =
                gr.getDisplayValue("priority") ||
                gr.getValue("priority") ||
                "Medium";

        }


        // =================================================
        // RISK CALCULATION
        // =================================================

        var priorityText =
            String(priority).toLowerCase();

        var riskLevel = "Low";

        var riskScore = 25;


        if (
            priorityText.indexOf("high") !== -1 ||
            priorityText.indexOf("critical") !== -1 ||
            priorityText === "1"
        ) {

            riskLevel = "High";
            riskScore = 85;

            highRisk++;

        } else if (
            priorityText.indexOf("medium") !== -1 ||
            priorityText === "2"
        ) {

            riskLevel = "Medium";
            riskScore = 55;

            mediumRisk++;

        } else {

            riskLevel = "Low";
            riskScore = 25;

            lowRisk++;
        }


        // =================================================
        // CASE CREATION DATE
        // =================================================

        var createdDate =
            gr.getValue("sys_created_on");


        // =================================================
        // SLA CALCULATION
        //
        // 0-24 hours  = ON TRACK
        // 24-48 hours = AT RISK
        // >48 hours   = BREACHED
        // =================================================

        var hoursElapsed = 0;

        if (createdDate) {

            var createdGDT =
                new GlideDateTime(createdDate);

            var nowGDT =
                new GlideDateTime();

            var difference =
                nowGDT.getNumericValue() -
                createdGDT.getNumericValue();

            hoursElapsed =
                Math.floor(
                    difference /
                    (1000 * 60 * 60)
                );
        }


        // =================================================
        // CHECK COMPLETED STATUS
        // =================================================

        var stageText =
            String(caseStage).toLowerCase();

        var isCompleted =
            stageText.indexOf("approved") !== -1 ||
            stageText.indexOf("resolved") !== -1 ||
            stageText.indexOf("completed") !== -1 ||
            stageText.indexOf("closed") !== -1;


        // =================================================
        // SLA STATUS
        // =================================================

        var slaStatus = "On Track";

        if (isCompleted) {

            onTrack++;

            resolvedCases++;

            totalResolutionDays +=
                Math.round(
                    hoursElapsed / 24
                );

        } else {

            if (hoursElapsed > 48) {

                slaStatus = "Breached";

                breached++;

            } else if (hoursElapsed > 24) {

                slaStatus = "At Risk";

                atRisk++;

            } else {

                slaStatus = "On Track";

                onTrack++;
            }
        }


        // =================================================
        // WATCHLIST
        // =================================================

        if (
            riskLevel === "High" ||
            slaStatus === "At Risk" ||
            slaStatus === "Breached"
        ) {

            var hoursLeft = 0;

            if (hoursElapsed < 48) {

                hoursLeft =
                    48 - hoursElapsed;
            }


            var timeRemaining = "";


            if (slaStatus === "Breached") {

                timeRemaining =
                    Math.abs(
                        hoursElapsed - 48
                    ) +
                    " hrs overdue";

            } else {

                timeRemaining =
                    hoursLeft +
                    " hrs remaining";
            }


            data.watchlistCases.push({

                case_id: caseId,

                student_name: studentName,

                case_type: caseType,

                case_stage: caseStage,

                priority: priority,

                risk_score: riskScore,

                risk_level: riskLevel,

                sla_status: slaStatus,

                hours_left: hoursLeft,

                time_remaining_str:
                    timeRemaining
            });
        }
    }


    // =====================================================
    // SLA STATISTICS
    // =====================================================

    data.slaStats.onTrack =
        onTrack;

    data.slaStats.atRisk =
        atRisk;

    data.slaStats.breached =
        breached;


    if (resolvedCases > 0) {

        data.slaStats.avgResolutionDays =
            Math.round(
                totalResolutionDays /
                resolvedCases
            );

    } else {

        data.slaStats.avgResolutionDays = 0;
    }


    // =====================================================
    // RISK DISTRIBUTION
    // =====================================================

    if (totalCases > 0) {

        data.riskDistribution = [

            {
                label: "High Risk",

                count: highRisk,

                percentage:
                    Math.round(
                        (highRisk / totalCases) * 100
                    ),

                color: "#ea5455"
            },

            {
                label: "Medium Risk",

                count: mediumRisk,

                percentage:
                    Math.round(
                        (mediumRisk / totalCases) * 100
                    ),

                color: "#ff9f43"
            },

            {
                label: "Low Risk",

                count: lowRisk,

                percentage:
                    Math.round(
                        (lowRisk / totalCases) * 100
                    ),

                color: "#00b074"
            }

        ];

    } else {

        data.riskDistribution = [

            {
                label: "High Risk",
                count: 0,
                percentage: 0,
                color: "#ea5455"
            },

            {
                label: "Medium Risk",
                count: 0,
                percentage: 0,
                color: "#ff9f43"
            },

            {
                label: "Low Risk",
                count: 0,
                percentage: 0,
                color: "#00b074"
            }

        ];
    }


    // =====================================================
    // SORT WATCHLIST
    // =====================================================

    data.watchlistCases.sort(
        function(a, b) {

            // Breached first

            if (
                a.sla_status === "Breached" &&
                b.sla_status !== "Breached"
            ) {
                return -1;
            }

            if (
                a.sla_status !== "Breached" &&
                b.sla_status === "Breached"
            ) {
                return 1;
            }


            // High risk first

            return (
                b.risk_score -
                a.risk_score
            );
        }
    );


    // =====================================================
    // LIMIT WATCHLIST
    // =====================================================

    if (
        data.watchlistCases.length > 10
    ) {

        data.watchlistCases =
            data.watchlistCases.slice(
                0,
                10
            );
    }


    // =====================================================
    // AI INSIGHT
    // =====================================================

    if (
        highRisk > 0 &&
        breached > 0
    ) {

        data.aiInsight =
            highRisk +
            " high-risk cases require attention, while " +
            breached +
            " cases have breached the 48-hour SLA. " +
            "Immediate advisor review is recommended.";

    } else if (
        highRisk > 0
    ) {

        data.aiInsight =
            highRisk +
            " high-risk cases have been identified. " +
            "Advisors should prioritize these cases for compliance review.";

    } else if (
        breached > 0
    ) {

        data.aiInsight =
            breached +
            " cases have breached the SLA target. " +
            "Immediate processing review is recommended.";

    } else {

        data.aiInsight =
            "Current visa case processing is within the defined SLA thresholds. Continue monitoring priority cases.";
    }

})();
